@Injectable({
  providedIn: 'root',
})
export class LearningService {
  private readonly data = signal<MainCategory[]>(ALL_DATA);

  getLearningData() {
    return this.data.asReadonly();
  }

  getPathBySlug(
    slug: string
  ):
    | { path: LearningPath; subcategory: Subcategory; mainCategory: MainCategory }
    | undefined {
    for (const mainCat of this.data()) {
      for (const subCat of mainCat.subcategories) {
        const foundPath = subCat.paths.find((p) => p.slug === slug);
        if (foundPath) {
          return {
            path: foundPath,
            subcategory: subCat,
            mainCategory: mainCat,
          };
        }
      }
    }
    return undefined;
  }

  getNavigationContext(currentPath: string): {
    prevStep?: LearningStep;
    nextStep?: LearningStep;
    parentPath?: LearningPath;
  } | undefined {
    for (const mainCat of this.data()) {
      for (const subCat of mainCat.subcategories) {
        for (const path of subCat.paths) {
          const index = path.steps.findIndex(s => s.path === currentPath);
          if (index !== -1) {
            return {
              prevStep: path.steps[index - 1],
              nextStep: path.steps[index + 1],
              parentPath: path
            };
          }
        }
      }
    }
    return undefined;
  }
}

